SELECT (SELECT COUNT(*) FROM loan_monthly_snapshot WHERE snapshot_date=DATE '2019-12-31' AND loan_status<>'Closed'), (SELECT ROUND(SUM(closing_balance)/1e6,1) FROM loan_monthly_snapshot WHERE snapshot_date=DATE '2019-12-31' AND loan_status<>'Closed'), (SELECT ROUND(100.0*COUNT(*) FILTER (WHERE days_past_due>=90)/COUNT(*),2) FROM loan_monthly_snapshot WHERE snapshot_date=DATE '2019-12-31' AND loan_status<>'Closed'), (SELECT ROUND(SUM(ecl_amount)/1e6,1) FROM ecl_provision_quarterly WHERE reporting_date=DATE '2019-12-31'), (SELECT ROUND(100*SUM(ecl_amount)/SUM(ead),2) FROM ecl_provision_quarterly WHERE reporting_date=DATE '2019-12-31'), (SELECT ROUND(SUM(original_amount)/1e6,1) FROM loan WHERE origination_date >= DATE '2019-01-01' AND origination_date < DATE '2020-01-01')
